mapper.select:
SELECT , l.name AS lab_name, l.code AS lab_code
FROM mentor m JOIN lab l ON l.id = m.lab_id
WHERE m.id = #{id}

SELECT , l.name AS lab_name, l.code AS lab_code
FROM mentor m JOIN lab l ON l.id = m.lab_id
WHERE m.user_id = #{userId}

SELECT , l.name AS lab_name, l.code AS lab_code
FROM mentor m JOIN lab l ON l.id = m.lab_id


        AND (m.name LIKE CONCAT('%', #{keyword}, '%')
             OR m.mentor_no LIKE CONCAT('%', #{keyword}, '%')
             OR m.research_direction LIKE CONCAT('%', #{keyword}, '%'))

    AND m.lab_id = #{labId}
    AND m.enabled = #{enabled}

ORDER BY m.lab_id, m.id
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM mentor m


        AND (m.name LIKE CONCAT('%', #{keyword}, '%')
             OR m.mentor_no LIKE CONCAT('%', #{keyword}, '%')
             OR m.research_direction LIKE CONCAT('%', #{keyword}, '%'))

    AND m.lab_id = #{labId}
    AND m.enabled = #{enabled}

SELECT , l.name AS lab_name, l.code AS lab_code, (SELECT COUNT(*) FROM final_assignment fa WHERE fa.mentor_id = m.id AND fa.batch_id = #{batchId} AND fa.status != 'REVOKED') AS confirmed_count, (SELECT COUNT(*) FROM offer o WHERE o.mentor_id = m.id AND o.batch_id = #{batchId} AND o.status IN ('OFFERED', 'CONFIRMED')) AS offered_count, (SELECT COUNT(DISTINCT i.application_id) FROM application_intent i WHERE i.mentor_id = m.id AND i.batch_id = #{batchId}) AS applicant_count FROM mentor m JOIN lab l ON l.id = m.lab_id
AND m.lab_id = #{labId}
ORDER BY m.lab_id, m.id

mapper.update:
UPDATE mentor
SET name = #{name}, title = #{title}, lab_id = #{labId},
    research_direction = #{researchDirection}, profile = #{profile},
    quota = #{quota}, enabled = #{enabled}
WHERE id = #{id}
